<script lang="ts">
  import { buyProperty, closeBusiness, formatCharacterMoney, getEconomicConditions, getMarketPrice, planBusinessManagementInNextFreeTime, removePlannedActivity, moveIntoOwnedProperty, rentHome, sellProperty, setPropertyRental, startBusiness, tradeInvestment } from './lib/simulation';
  import type { BusinessType, Character, PropertyType } from './lib/types';
  import GameChoice from './GameChoice.svelte';
  let { character, onChange, view = 'all' }: { character: Character; onChange: (next: Character) => void; view?: 'all' | 'property' | 'investments' | 'business' } = $props();
  const scale = $derived(character.currencyScale ?? 1);
  const properties = $derived(character.properties ?? []);
  const holdings = $derived(character.investments ?? []);
  const businesses = $derived(character.businesses ?? []);
  const economy = $derived(getEconomicConditions(character));
  const rate = (value:number)=>((value*100).toFixed(1)+'%');
  let propertyType = $state<PropertyType>('apartment'); let propertyName = $state(''); let propertyPrice = $state(''); let downPayment = $state(''); let mortgageRate = $state('7'); let mortgageTerm = $state('20'); let primaryResidence = $state(true);
  let rentalType = $state<PropertyType>('apartment'); let annualRent = $state(''); let rentalIncome = $state('');
  let units = $state('1'); let businessType = $state<BusinessType>('retail'); let businessName = $state(''); let businessCapital = $state('');
  const propertyCatalog = [
    {id:'city-studio',name:'City studio apartment',type:'apartment' as const,price:42000,down:8400,growth:0.028,volatility:'Low',rentalYield:0.052,description:'Compact urban unit with steady rental demand.'},
    {id:'family-apartment',name:'Family apartment',type:'apartment' as const,price:78000,down:15600,growth:0.032,volatility:'Moderate',rentalYield:0.048,description:'Larger apartment suited to long-term tenants.'},
    {id:'suburban-house',name:'Suburban family house',type:'house' as const,price:125000,down:25000,growth:0.036,volatility:'Moderate',rentalYield:0.043,description:'Owner-occupier demand with higher upkeep.'},
    {id:'rental-house',name:'Multi-room rental house',type:'house' as const,price:165000,down:33000,growth:0.04,volatility:'Higher',rentalYield:0.061,description:'Higher potential rent with greater maintenance exposure.'}
  ];
  const businessCatalog = [
    {id:'neighborhood-retail',name:'Neighborhood retail shop',type:'retail' as const,capital:25000,growth:'Steady',volatility:'Moderate',cashIntensity:'High',profitability:'Moderate',margin:'8–14%',description:'Inventory-led local shop with repeat customers.'},
    {id:'online-store',name:'Online store',type:'online' as const,capital:12000,growth:'Fast',volatility:'High',cashIntensity:'Low',profitability:'Variable',margin:'10–22%',description:'Digital sales with lower premises costs and higher competition.'},
    {id:'local-cafe',name:'Local cafe',type:'cafe' as const,capital:40000,growth:'Moderate',volatility:'High',cashIntensity:'High',profitability:'Moderate',margin:'6–12%',description:'Location-sensitive food service with staffing and stock costs.'}
  ];
  let notice = $state('');
  function amount(v:string){const n=Number(v);return Number.isFinite(n)?Math.floor(n):0}
  function run(action:()=>Character,message:string){const next=action();if(next===character){notice='Action unavailable. Check your age, cash, property status, and limits.';return;}onChange(next);notice=message;}
  function selectProperty(item: typeof propertyCatalog[number]) { propertyType=item.type; propertyName=item.name; propertyPrice=String(Math.round(item.price*scale)); downPayment=String(Math.round(item.down*scale)); }
  function purchase(){run(()=>buyProperty(character,propertyType,propertyName,amount(propertyPrice),amount(downPayment),Number(mortgageRate)/100,amount(mortgageTerm),primaryResidence),'Property purchased.');propertyName='';}
  function rent(){run(()=>rentHome(character,rentalType,amount(annualRent)),'Rental home selected.');}
  function listRent(propertyId:string){run(()=>setPropertyRental(character,propertyId,true,amount(rentalIncome)),'Property listed for rent.');}
  function stopRent(propertyId:string){run(()=>setPropertyRental(character,propertyId,false),'Rental listing ended.');}
  function buy(type:'stock-index'|'gold'){run(()=>tradeInvestment(character,type,'buy',amount(units)),'Investment purchased.');}
  function sell(type:'stock-index'|'gold'){run(()=>tradeInvestment(character,type,'sell',amount(units)),'Investment sold.');}
  function openBusiness(item: typeof businessCatalog[number]){run(()=>startBusiness(character,item.name,item.type,Math.round(item.capital*scale)),'Business started.');}
  function planManagement(businessId:string){const existing=(character.weeklyPlan?.activities??[]).find((item)=>item.action?.kind==='business'&&item.action.businessId===businessId);if(existing){onChange(removePlannedActivity(character,existing.id));notice='Management removed from this week.';return;}const result=planBusinessManagementInNextFreeTime(character,businessId);if(result.issue){notice=result.message??'Could not add management this week.';return;}onChange(result.character);notice='Management added · 12 stamina.';}
</script>
<section class="assets-panel">
  <div class="assets-heading"><div><small>{view === 'property' ? 'HOUSING & PROPERTY' : view === 'investments' ? 'MARKET PORTFOLIO' : view === 'business' ? 'BUSINESS OPERATIONS' : 'LONG-TERM WEALTH'}</small><h2>{view === 'property' ? 'Property & housing' : view === 'investments' ? 'Investments' : view === 'business' ? 'Business ownership' : 'Property & investments'}</h2></div>{#if view === 'all'}<span>{properties.length} properties · {businesses.length} businesses</span>{/if}</div>
  <div class="economy-strip"><div><small>ECONOMY</small><strong class={economy.cycle}>{economy.cycle}</strong></div><div><small>INFLATION</small><strong>{rate(economy.inflationRate)}</strong></div><div><small>GROWTH</small><strong>{rate(economy.growthRate)}</strong></div><div><small>BASE RATE</small><strong>{rate(economy.baseInterestRate)}</strong></div></div>
  <p class="economy-note">Living costs and market prices respond to the economy. Stocks can fall in downturns; gold may react differently when inflation rises. Rates and returns are simplified game estimates.</p>
  {#if view === 'all' || view === 'property'}
  <details open={view !== 'all'}><summary>Housing: rent or own</summary>
    <div class="current-home"><small>CURRENT ARRANGEMENT</small><strong>{character.primaryResidenceId ? properties.find((p)=>p.id===character.primaryResidenceId)?.name ?? 'Owned home' : character.rentalHome ? 'Renting · '+character.rentalHome.type : 'Current household arrangement'}</strong>{#if character.rentalHome}<span>{formatCharacterMoney(character,character.rentalHome.annualRent)} annual rent</span>{/if}</div>
    <div class="form-grid"><div class="choice-field"><span>Rental home type</span><GameChoice label="Rental home type" value={rentalType} options={[{value:'apartment',label:'Apartment',detail:'Lower upkeep and rent'},{value:'house',label:'House',detail:'More space, higher cost'}]} onSelect={(value) => rentalType = value as PropertyType} columns={2}/></div><label>Annual rent<input type="number" min="1" bind:value={annualRent} placeholder={String(6000*scale)}/></label></div><button onclick={rent} disabled={character.age<18}>Choose rental home</button>
    <h3>Available properties</h3>
    <div class="catalog-grid property-catalog">
      {#each propertyCatalog as item (item.id)}
        <article class="catalog-item"><div class="catalog-item-heading"><strong>{item.name}</strong><span>{item.type}</span></div><p>{item.description}</p><div><span>Asking price</span><b>{formatCharacterMoney(character,item.price*scale)}</b></div><div><span>Minimum down payment</span><b>{formatCharacterMoney(character,item.down*scale)}</b></div><div><span>Annual growth profile</span><b>{rate(item.growth)}</b></div><div><span>Market volatility</span><b>{item.volatility}</b></div><div><span>Indicative rental yield</span><b>{rate(item.rentalYield)}</b></div><button onclick={()=>selectProperty(item)}>Select property</button></article>
      {/each}
    </div>
    <div class="form-grid"><label>Down payment<input type="number" min="1" bind:value={downPayment}/></label><label>Mortgage rate %<input type="number" min="0" max="50" step="0.5" bind:value={mortgageRate}/></label><label>Term (years)<input type="number" min="1" max="30" bind:value={mortgageTerm}/></label></div><label class="check"><input type="checkbox" bind:checked={primaryResidence}/> Make this my primary residence</label><button class="primary" onclick={purchase} disabled={character.age<18 || properties.length>=5 || !propertyName || !propertyPrice}>Buy selected property</button><small class="hint">Select a prebuilt property to populate its price and required down payment. Mortgages require at least 20% down. Purchases and sales have 1% fees; positive sale gains are taxed at 10%. Maintenance is estimated at 1% of value annually.</small>
    {#each properties as property}<div class="asset-row"><div><strong>{property.name}</strong><small>{property.type} · value {formatCharacterMoney(character,property.marketValue)} · maintenance {formatCharacterMoney(character,property.annualMaintenance)}/yr</small><small>{property.id===character.primaryResidenceId?'Primary residence':property.rentedOut?'Rented out':'Not occupied'}</small></div><div class="asset-actions">{#if property.id!==character.primaryResidenceId && !property.rentedOut}<button onclick={()=>run(()=>moveIntoOwnedProperty(character,property.id),'Moved into property.')}>Move in</button>{/if}<button class="quiet" onclick={()=>run(()=>sellProperty(character,property.id),'Property sold and mortgage settled.')}>Sell</button></div></div>{#if property.id!==character.primaryResidenceId}<div class="form-grid rent-tools"><label>Annual rental income<input type="number" min="1" bind:value={rentalIncome} placeholder={String(8000*scale)}/></label>{#if property.rentedOut}<button onclick={()=>stopRent(property.id)}>Stop renting</button>{:else}<button onclick={()=>listRent(property.id)}>List for rent</button>{/if}</div>{/if}{/each}
  </details>
  {/if}
  {#if view === 'all' || view === 'investments'}
  <details open={view !== 'all'}><summary>Stocks & gold <span>Portfolio {formatCharacterMoney(character,holdings.reduce((sum,h)=>sum+h.units*getMarketPrice(character,h.type),0))}</span></summary>
    <div class="market-grid"><div><small>BROAD MARKET INDEX · PER UNIT</small><strong>{formatCharacterMoney(character,getMarketPrice(character,'stock-index'))}</strong><span>{holdings.find((h)=>h.type==='stock-index')?.units??0} units · diversified market exposure</span></div><div><small>GOLD · PER UNIT</small><strong>{formatCharacterMoney(character,getMarketPrice(character,'gold'))}</strong><span>{holdings.find((h)=>h.type==='gold')?.units??0} units · commodity exposure</span></div></div>
    <h3>Open positions</h3>
    {#if holdings.length===0}<p class="hint">No open positions. Select an instrument below to place a buy order.</p>{:else}
      {#each holdings as holding}
        {@const marketPrice=getMarketPrice(character,holding.type)}
        {@const marketValue=marketPrice*holding.units}
        {@const costBasis=holding.averageCost*holding.units}
        <div class="asset-row"><div><strong>{holding.type==='stock-index'?'Broad market index':'Gold'}</strong><small>{holding.units} units · average cost {formatCharacterMoney(character,holding.averageCost)} · current {formatCharacterMoney(character,marketPrice)}</small></div><div class="position-value"><b>{formatCharacterMoney(character,marketValue)}</b><small class:positive={marketValue>=costBasis} class:negative={marketValue<costBasis}>{marketValue>=costBasis?'+':''}{formatCharacterMoney(character,marketValue-costBasis)} unrealized</small></div></div>
      {/each}
    {/if}
    <label>Units<input type="number" min="1" max="1000000" bind:value={units}/></label><div class="trade-grid"><div><strong>Index fund</strong><div><button onclick={()=>buy('stock-index')}>Buy</button><button onclick={()=>sell('stock-index')}>Sell</button></div></div><div><strong>Gold</strong><div><button onclick={()=>buy('gold')}>Buy</button><button onclick={()=>sell('gold')}>Sell</button></div></div></div>
    <small class="hint">Trading uses market orders, whole units and cash settlement. Brokerage is 0.5% on each trade; realized gains incur 10% capital-gains tax. Buy fees enter cost basis, while sell fees and taxes reduce proceeds. Prices update annually and returns are not guaranteed.</small>
  </details>
  {/if}
  {#if view === 'all' || view === 'business'}
  <details open={view !== 'all'}><summary>Start or manage a business <span>{businesses.length}/3</span></summary>
    {#each businesses as business}<div class="asset-row"><div><strong>{business.name}</strong><small>{business.type} · value {formatCharacterMoney(character,business.valuation)} · performance {business.performance}/100</small><small>{business.type==='retail'?'Steady growth · moderate volatility · high cash intensity · 8–14% typical margin':business.type==='online'?'Fast growth · high volatility · low cash intensity · 10–22% typical margin':'Moderate growth · high volatility · high cash intensity · 6–12% typical margin'}</small></div><div class="asset-actions"><button class:planned={(character.weeklyPlan?.activities??[]).some((item)=>item.action?.kind==='business'&&item.action.businessId===business.id)} onclick={()=>planManagement(business.id)}>{(character.weeklyPlan?.activities??[]).some((item)=>item.action?.kind==='business'&&item.action.businessId===business.id)?'Remove management plan':'Manage this week · 12 stamina'}</button><button class="quiet" onclick={()=>run(()=>closeBusiness(character,business.id),'Business sold.')}>Sell</button></div></div>{/each}
    <h3>Prebuilt business opportunities</h3>
    <div class="catalog-grid business-catalog">
      {#each businessCatalog as item (item.id)}
        <article class="catalog-item"><div class="catalog-item-heading"><strong>{item.name}</strong><span>{item.type}</span></div><p>{item.description}</p><div><span>Startup capital</span><b>{formatCharacterMoney(character,item.capital*scale)}</b></div><div><span>Growth profile</span><b>{item.growth}</b></div><div><span>Volatility</span><b>{item.volatility}</b></div><div><span>Cash intensity</span><b>{item.cashIntensity}</b></div><div><span>Typical operating margin</span><b>{item.margin}</b></div><div><span>Profitability outlook</span><b>{item.profitability}</b></div><button class="primary" disabled={character.age<18 || businesses.length>=3 || character.money<item.capital*scale} onclick={()=>openBusiness(item)}>Start this business</button></article>
      {/each}
    </div><small class="hint">Each opportunity has a defined starting capital requirement. Actual yearly results remain uncertain and depend on business performance and economic conditions. Management uses 12 stamina and costs 1% of invested capital.</small>
  </details>
  {/if}
  {#if notice}<p class="notice" role="status">{notice}</p>{/if}
</section>
<style>
.catalog-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin:10px 0}.catalog-item{display:grid;gap:6px;padding:11px;border:1px solid var(--line);border-radius:11px;background:var(--surface)}.catalog-item-heading{display:flex;justify-content:space-between;gap:8px;align-items:flex-start}.catalog-item-heading strong{font-size:12px}.catalog-item-heading span{font-size:9px;color:var(--muted);text-transform:uppercase}.catalog-item p{margin:0 0 4px;font-size:10px;color:var(--muted);line-height:1.45}.catalog-item>div:not(.catalog-item-heading){display:flex;justify-content:space-between;gap:8px;font-size:10px}.catalog-item>div span{color:var(--muted)}.catalog-item button{margin-top:4px}.position-value{text-align:right;white-space:nowrap}.position-value small{display:block}.position-value .positive{color:var(--success)}.position-value .negative{color:var(--danger)}.assets-panel{border:1px solid color-mix(in srgb,var(--line-strong) 9%, transparent);border-radius:16px;padding:16px;margin:16px 0;background:color-mix(in srgb,var(--surface-raised) 2%, transparent)}.assets-heading{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:8px}.assets-heading small,.assets-heading span,.hint,.current-home small,.current-home span,.market-grid small,.market-grid span,.asset-row small{color:var(--muted);font-size:11px}.assets-heading h2{font-size:17px;margin:3px 0}.economy-strip{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;margin:10px 0}.economy-strip>div{padding:8px 6px;border-radius:8px;background:color-mix(in srgb,var(--surface-raised) 4%, transparent);min-width:0}.economy-strip small,.economy-strip strong{display:block}.economy-strip small{font-size:9px;color:var(--muted)}.economy-strip strong{font-size:11px;text-transform:capitalize;margin-top:4px}.economy-strip .recession{color:var(--danger)}.economy-strip .expansion{color:var(--accent)}.economy-note{font-size:10px;line-height:1.5;color:var(--muted);margin:0 0 10px}.assets-panel details{border-top:1px solid color-mix(in srgb,var(--line-strong) 8%, transparent);padding:12px 0}.assets-panel summary{cursor:pointer;font-size:13px;font-weight:700;display:flex;justify-content:space-between;gap:8px}.assets-panel summary span{color:var(--muted);font-weight:500}.current-home,.market-grid>div{padding:12px;background:color-mix(in srgb,var(--surface-raised) 3.5%, transparent);border-radius:10px;margin:8px 0}.current-home strong,.current-home span,.market-grid strong,.market-grid span{display:block;margin-top:4px}.current-home strong,.market-grid strong{font-size:14px}.choice-field{display:grid;gap:5px;margin:8px 0;color:var(--muted);font-size:11px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}label{display:grid;gap:5px;margin:9px 0;color:var(--muted);font-size:11px}input{width:100%;min-width:0;padding:10px;border:1px solid color-mix(in srgb,var(--line-strong) 13%, transparent);border-radius:8px;background:var(--surface);color:var(--text);font:inherit;font-size:12px}.assets-panel button{padding:9px 12px;border-radius:8px;border:1px solid color-mix(in srgb,var(--line-strong) 13%, transparent);background:color-mix(in srgb,var(--surface-raised) 6%, transparent);color:inherit;font-size:11px;font-weight:650}.assets-panel button.primary{background:var(--accent,var(--accent-strong));color:var(--on-accent);border:0}.assets-panel button.planned{border-color:var(--accent);background:var(--accent-soft);color:var(--accent)}.assets-panel button.quiet{padding:6px 9px}.check{display:flex;align-items:center;gap:8px}.check input{width:auto}.asset-row{display:flex;justify-content:space-between;gap:10px;padding:11px 0;border-bottom:1px solid color-mix(in srgb,var(--line-strong) 5%, transparent)}.asset-row strong,.asset-row small{display:block}.asset-row strong{font-size:12px}.asset-row small{margin-top:3px}.asset-actions{display:flex;flex-direction:column;gap:5px}.rent-tools{align-items:end}.market-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.trade-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.trade-grid>div{padding:10px;border:1px solid color-mix(in srgb,var(--line-strong) 8%, transparent);border-radius:10px}.trade-grid strong{font-size:12px;display:block;margin-bottom:8px}.trade-grid>div>div{display:flex;gap:6px}.hint{display:block;line-height:1.5;margin:8px 0}.notice{font-size:12px;color:var(--accent)}@media(max-width:560px){.catalog-grid{grid-template-columns:1fr}}@media(max-width:460px){.assets-panel{padding:12px}.form-grid{grid-template-columns:1fr}.assets-heading{align-items:flex-start;flex-direction:column}.asset-row{align-items:flex-start}}
</style>